:root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --border: #d5dae1;
  --text: #16202b;
  --muted: #56616e;
  --accent: #0f766e;
  --accent-soft: #e6f2f1;
  --focus: #1d4ed8;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #12171d;
    --surface: #1a2029;
    --border: #303a46;
    --text: #e7ecf2;
    --muted: #a3aebc;
    --accent: #5eead4;
    --accent-soft: #16302f;
    --focus: #93c5fd;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 2rem 1rem 4rem;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

#app {
  max-width: 44rem;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.page-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

h2 {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}

#feed-heading {
  margin-bottom: -0.5rem;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
}

form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.7rem;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 6rem;
}

.hint {
  margin: 0;
  font-size: 0.82rem;
  color: var(--muted);
}

.hint code {
  background: var(--accent-soft);
  border-radius: 4px;
  padding: 0 0.25em;
  font-size: 0.95em;
}

.primary {
  align-self: flex-start;
  font: inherit;
  font-weight: 600;
  color: #ffffff;
  background: #0f766e;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.55rem 1.1rem;
  cursor: pointer;
}

.primary:hover {
  background: #0b5f58;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

#results-line {
  margin: 0.75rem 0 0;
  color: var(--muted);
  min-height: 1.55em;
}

#results-line:empty {
  display: none;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid transparent;
  border-radius: 12px;
  padding: 1rem 1.25rem;
}

.note[aria-current='true'] {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.note-avatar {
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
}

.note-heading {
  margin: 0;
  flex: 1;
  font-size: 1.15rem;
}

.note-title {
  font: inherit;
  color: inherit;
  text-align: left;
  background: none;
  border: 0;
  border-radius: 6px;
  padding: 0.15rem 0;
  width: 100%;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
}

.note-body {
  margin-top: 0.5rem;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--focus);
}

.note-time {
  display: block;
  margin-top: 0.6rem;
  font-size: 0.8rem;
  color: var(--muted);
}

.empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  border: 1px dashed var(--border);
  border-radius: 12px;
}

